    27→export async function gachaPull(pullType: 'single' | 'multi'): Promise<GachaPullResult> {
    28→  // getUser()는 토큰을 서버 검증 후 만료 시 자동 갱신
    29→  const { data: { user } } = await supabase.auth.getUser();
    30→  if (!user) {
