    23→// R 80% (10종 균등 배분), SR 19.3% (6종 균등 배분), UR 0.7% (2종 균등 배분)
    24→const SR_W  = 19.3 / 6;   // ≈ 3.217%
    25→const POOL = [
    26→  // ── R등급 ──
    27→  { id: 'log',     grade: 'R',  weight: 8 },
    28→  { id: 'swap',    grade: 'R',  weight: 8 },
    29→  { id: 'sum',     grade: 'R',  weight: 8 },
    30→  { id: 'fork',    grade: 'R',  weight: 8 },
    31→  { id: 'seed',    grade: 'R',  weight: 8 },
    32→  { id: 'session', grade: 'R',  weight: 8 },
    33→  { id: 'branch',  grade: 'R',  weight: 8 },
    34→  { id: 'hook',    grade: 'R',  weight: 8 },
    35→  { id: 'socket',  grade: 'R',  weight: 8 },
    36→  { id: 'index',   grade: 'R',  weight: 8 },
    37→  // ── SR등급 ──
    38→  { id: 'hacker',   grade: 'SR', weight: SR_W },
    39→  { id: 'miner',    grade: 'SR', weight: SR_W },
    40→  { id: 'maehwa',   grade: 'SR', weight: SR_W },
    41→  { id: 'archieve', grade: 'SR', weight: SR_W },
    42→  { id: 'glitch',   grade: 'SR', weight: SR_W },
    43→  { id: 'noise',    grade: 'SR', weight: SR_W },
    44→  // ── UR등급 ──
    45→  { id: 'sentinel', grade: 'UR', weight: 0.35 },
    46→  { id: 'legacy',   grade: 'UR', weight: 0.35 },
    47→];
    48→
    49→function pullOne(): { id: string; grade: string } {
    50→  const total = POOL.reduce((s, c) => s + c.weight, 0);
    51→  let r = Math.random() * total;
    52→  for (const c of POOL) {
    53→    r -= c.weight;
    54→    if (r <= 0) return { id: c.id, grade: c.grade };
    55→  }
    56→  return { id: POOL[POOL.length - 1].id, grade: POOL[POOL.length - 1].grade };
    57→}
