    89→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    90→      { global: { headers: { Authorization: authHeader } } }
    91→    );
    92→
    93→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    94→    if (authError || !user) {
    95→      return new Response(
    96→        JSON.stringify({ error: 'Unauthorized' }),
    97→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    98→      );
    99→    }
   100→
   101→    const supabaseAdmin = createClient(
   102→      Deno.env.get('SUPABASE_URL') ?? '',
   103→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
   104→    );
   105→
   106→    // ── 1. SKOR 잔액 + 보유 캐릭터 + 보유 배경화면 병렬 조회 ────────
   107→    const [{ data: skorData }, { data: owned }, { data: ownedWp }] = await Promise.all([
   108→      supabaseAdmin.from('user_skor').select('balance').eq('user_id', user.id).single(),
   109→      supabaseAdmin.from('user_characters').select('character_id').eq('user_id', user.id),
   110→      supabaseAdmin.from('user_wallpapers').select('wallpaper_id').eq('user_id', user.id),
   111→    ]);
   112→
   113→    const balance = skorData?.balance ?? 0;
   114→    if (balance < cost) {
   115→      return new Response(
   116→        JSON.stringify({ error: 'Insufficient SKOR', balance }),
   117→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   118→      );
   119→    }
   120→
   121→    // ── 2. 슬롯별 결정: 각 슬롯은 배경화면 또는 캐릭터 중 하나
   122→    //       총합 = count, 추가 드롭 없음 ────────────────────────────────
   123→    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
   124→    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));
   125→
   126→    const characters: { id: string; grade: string; isNew: boolean }[] = [];
   127→    const wallpapers: { id: string; isNew: boolean }[] = [];
   128→
   129→    for (let i = 0; i < count; i++) {
   130→      if (Math.random() < WP_DROP_CHANCE) {
   131→        // 이 슬롯은 배경화면
   132→        const wp = pullWallpaper();
   133→        wallpapers.push({ id: wp.id, isNew: !ownedWpSet.has(wp.id) });
   134→        ownedWpSet.add(wp.id); // 같은 pull 내 중복 isNew 방지
   135→      } else {
   136→        // 이 슬롯은 캐릭터
   137→        const char = pullOne();
   138→        characters.push({ id: char.id, grade: char.grade, isNew: !ownedSet.has(char.id) });
   139→      }
   140→    }
   141→
   142→    // ── 3. 신규 배경화면 등록 ────────────────────────────────────────────
   143→    const newWps = wallpapers
   144→      .filter(w => w.isNew)
   145→      .map(w => ({ user_id: user.id, wallpaper_id: w.id }));
   146→
   147→    // ── 4. 신규 캐릭터 등록 + 중복 카운트 증가 + SKOR 차감 병렬 처리 ─────
   148→    // 같은 캐릭터가 10연차에서 중복 등장할 수 있으므로 횟수 집계 후 처리
   149→    const newChars = [...new Map(
   150→      characters
   151→        .filter(c => c.isNew)
   152→        .map(c => [c.id, { user_id: user.id, character_id: c.id }])
   153→    ).values()];
   154→
   155→    // 중복 캐릭터별 횟수 집계 (같은 캐릭터가 10연차에서 2번 나오면 +2)
   156→    const dupCountMap = new Map<string, number>();
   157→    characters.filter(c => !c.isNew).forEach(c => {
   158→      dupCountMap.set(c.id, (dupCountMap.get(c.id) ?? 0) + 1);
   159→    });
   160→
   161→    const newBalance = balance - cost;
   162→    const [charResult, , , skorResult] = await Promise.all([
   163→      newChars.length > 0
   164→        ? supabaseAdmin.from('user_characters').upsert(newChars, { onConflict: 'user_id,character_id' })
   165→        : Promise.resolve({ error: null }),
   166→      // 중복 카운트 증가: RPC로 atomic increment
   167→      dupCountMap.size > 0
   168→        ? Promise.all([...dupCountMap.entries()].map(([charId, inc]) =>
   169→            supabaseAdmin.rpc('increment_duplicate_count', {
   170→              p_user_id: user.id,
   171→              p_character_id: charId,
   172→              p_amount: inc,
   173→            })
   174→          ))
   175→        : Promise.resolve(null),
   176→      // 신규 배경화면 등록
   177→      newWps.length > 0
   178→        ? supabaseAdmin.from('user_wallpapers').upsert(newWps, { onConflict: 'user_id,wallpaper_id' })
   179→        : Promise.resolve({ error: null }),
   180→      supabaseAdmin.from('user_skor').upsert(
   181→        { user_id: user.id, balance: newBalance, updated_at: new Date().toISOString() },
   182→        { onConflict: 'user_id' }
   183→      ),
   184→    ]);
   185→
   186→    if (charResult && 'error' in charResult && charResult.error) {
   187→      console.error('user_characters upsert 실패:', charResult.error);
   188→      return new Response(
   189→        JSON.stringify({ error: 'Failed to save characters', detail: charResult.error }),
   190→        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   191→      );
   192→    }
   193→    if (skorResult && 'error' in skorResult && skorResult.error) {
   194→      console.error('user_skor upsert 실패:', skorResult.error);
   195→    }
   196→
   197→    // ── 6. 응답 ───────────────────────────────────────────────────────
   198→    const hasUR = characters.some(c => c.grade === 'UR');
   199→
   200→    return new Response(
   201→      JSON.stringify({
   202→        success: true,
   203→        video: hasUR ? 'red' : 'green',
   204→        characters,
   205→        wallpapers,
   206→        remainingSkor: Math.floor(newBalance),
   207→      }),
   208→      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   209→    );
   210→  } catch (error) {
   211→    console.error('Unexpected error:', error);
   212→    return new Response(
   213→      JSON.stringify({ error: 'Internal server error' }),
   214→      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   215→    );
   216→  }
   217→});
