   253→  private async startPull(type: 'single' | 'multi') {
   254→    const cost = type === 'multi' ? 900 : 100;
   255→    if (this.skorBalance < 0) {
   256→      const errMsg = this.add.text(200, 370, '잔액 확인 중... 잠시 후 다시 시도하세요', {
   257→        fontSize: '13px', color: '#ffaa44',
   258→        stroke: '#000000', strokeThickness: 3,
   259→        backgroundColor: '#00000099',
   260→        padding: { x: 10, y: 5 },
   261→      }).setOrigin(0.5);
   262→      this.time.delayedCall(2000, () => { if (errMsg.active) errMsg.destroy(); });
   263→      return;
   264→    }
   265→    if (this.skorBalance < cost) {
   266→      const errMsg = this.add.text(200, 370, `SKOR 부족  (보유 ${Math.floor(this.skorBalance)} / 필요 ${cost})`, {
   267→        fontSize: '13px', color: '#ff5555',
   268→        stroke: '#000000', strokeThickness: 3,
   269→        backgroundColor: '#00000099',
   270→        padding: { x: 10, y: 5 },
   271→      }).setOrigin(0.5);
   272→      this.time.delayedCall(2200, () => { if (errMsg.active) errMsg.destroy(); });
   273→      return;
   274→    }
   275→
   276→    this.clearUI();
   277→
   278→    const count = type === 'multi' ? 10 : 1;
   279→
   280→    try {
   281→      // ① 영상(6초) + API 호출 병렬 실행 — 영상 보는 동안 응답 대기
   282→      const [result] = await Promise.all([
   283→        gachaPull(type),
   284→        this.playCommonVideo(),
   285→      ]);
   286→
   287→      if (!this.scene.isActive()) return;
   288→
   289→      this.pullResults = result.characters;
   290→      this.wpResults = result.wallpapers ?? [];
   291→      this.remainingSkor = result.remainingSkor;
   292→      // 슬롯 순서 보존: 캐릭터 → 배경 순 통합 큐
   293→      this.revealItems = [
   294→        ...result.characters.map(c => ({ kind: 'character' as const, data: c })),
   295→        ...(result.wallpapers ?? []).map(w => ({ kind: 'wallpaper' as const, data: w })),
   296→      ];
   297→      this.revealItemIndex = 0;
   298→
   299→      // ① 결과의 신규 캐릭터 즉시 저장 (sync 실패 대비 fallback)
   300→      result.characters.filter(c => c.isNew).forEach(c => addOwnedCharacter(c.id));
   301→      // ① 중복 캐릭터 각성 카운트 업데이트
   302→      result.characters.filter(c => !c.isNew).forEach(c => {
   303→        setDuplicateCount(c.id, getDuplicateCount(c.id) + 1);
   304→      });
   305→      // ① 신규 배경화면 즉시 저장 (sync 실패 대비 fallback)
   306→      this.wpResults.filter(w => w.isNew).forEach(w => addOwnedWallpaper(w.id));
   307→      // ② 서버 DB 전체 동기화 (비동기, 에러 로그만)
   308→      syncOwnedCharacters().catch(e => console.error('[GachaScene] syncOwnedCharacters 실패:', e));
   309→      syncOwnedWallpapers().catch(e => console.error('[GachaScene] syncOwnedWallpapers 실패:', e));
   310→
   311→      // ② 터미널 애니메이션 (UR이면 중반부터 빨간 에러 스타일로 전환)
   312→      const isUR = result.video === 'red'
   313→      this.skipTerminal = false;
   314→      this.clearUI();
   315→      this.add.rectangle(200, 300, 400, 600, 0x000000);
   316→      this.drawTerminalChrome(false); // 항상 초록으로 시작
   317→      this.addSkipButton(() => { this.skipTerminal = true; });
   318→      await this.runTerminalAnimation(count, isUR);
   319→      this.skipTerminal = false;
   320→
   321→      // ③ 캐릭터별 개인 영상 + 배경화면 이미지 동적 로드 → 리빌
   322→      await Promise.all([
   323→        this.loadCharVideos(result.characters.map(c => c.id)),
   324→        this.loadWallpaperBgs(this.wpResults.map(w => w.id)),
   325→      ]);
   326→
   327→      this.showNextReveal();
   328→    } catch {
   329→      if (!this.scene.isActive()) return;
   330→      await this.typeLines([
   331→        '> CONNECTION ERROR',
   332→        '> Retrying in 3s...',
   333→      ], 30);
   334→      this.time.delayedCall(3000, () => this.buildLobby());
   335→    }
   336→  }
