   387→  /** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
   388→  private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
   389→    vid.setDisplaySize(canvasW, canvasH); // 초기값
   390→
   391→    const applyContain = () => {
   392→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   393→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   394→      const nw = el?.videoWidth  || 0;
   395→      const nh = el?.videoHeight || 0;
   396→      if (nw > 0 && nh > 0) {
   397→        const scale = Math.max(canvasW / nw, canvasH / nh);
   398→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   399→      }
   400→    };
   401→
   402→    vid.once('play', applyContain);
   403→    this.time.delayedCall(100, applyContain);
   404→    this.time.delayedCall(500, applyContain);
   405→  }
