   960→  private sleep(ms: number): Promise<void> {
   961→    return new Promise(resolve => {
   962→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   963→      this.time.delayedCall(ms, resolve);
   964→    });
   965→  }
