   288→  // ── 그리드 빌더 ─────────────────────────────────────────────────────────
   289→
   290→  private buildCharacterGrid() {
   291→    this.cardHighlights.clear();
   292→    this.coresGfx = this.add.graphics();
   293→    CHARACTERS.forEach((char, index) => {
   294→      const col = index % COLS;
   295→      const row = Math.floor(index / COLS);
   296→      const x = GRID_LEFT + col * (CARD_W + GAP_X) + CARD_W / 2;
   297→      const y = GRID_TOP + row * (CARD_H + GAP_Y) + CARD_H / 2;
   298→      this.createCharacterCard(char, x, y);
   299→    });
   300→    this.cardsContainer.add(this.coresGfx);
   301→
   302→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   303→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   304→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   305→  }
   306→
   307→  private buildWallpaperGrid() {
   308→    this.wpHighlights.clear();
   309→    this.ownedWpIds = getOwnedWallpapers();
   310→    this.selectedWpId = getSelectedWallpaper();
   311→
   312→    const availableWps = WALLPAPERS.filter(w => AVAILABLE_WP_IDS.includes(w.id));
   313→    availableWps.forEach((wp, index) => {
   314→      const col = index % WP_COLS;
   315→      const row = Math.floor(index / WP_COLS);
   316→      const x = WP_GRID_LEFT + col * (WP_CARD_W + WP_GAP_X) + WP_CARD_W / 2;
   317→      const y = WP_GRID_TOP + row * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H / 2;
   318→      this.createWallpaperCard(wp, x, y);
   319→    });
   320→
   321→    const totalRows = Math.ceil(availableWps.length / WP_COLS);
   322→    const contentBottom = WP_GRID_TOP + (totalRows - 1) * (WP_CARD_H + WP_GAP_Y) + WP_CARD_H + 10;
   323→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   324→  }
   325→
   326→  private switchTab(tab: 'character' | 'wallpaper') {
   327→    if (this.activeTab === tab) return;
   328→    this.activeTab = tab;
   329→    this.scrollOffset = 0;
   330→    this.hasDragged = false;
   331→    this.cardsContainer.setY(0);
   332→    this.updateBgForTab();
   333→
   334→    // 컨테이너 내 카드 오브젝트 전부 제거
   335→    this.cardsContainer.removeAll(true);
   336→    this.cardHighlights.clear();
   337→    this.wpHighlights.clear();
   338→
   339→    // 탭 버튼 스타일 갱신
   340→    if (tab === 'character') {
   341→      this.charTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   342→      this.charTabLabel.setColor('#ffffff');
   343→      this.wpTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   344→      this.wpTabLabel.setColor('#888888');
   345→
   346→      this.buildCharacterGrid();
   347→
   348→      // 헤더 텍스트 갱신
   349→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   350→      this.headerNameText.setText(`현재: ${def.name}`).setColor(def.gradeColor);
   351→    } else {
   352→      this.wpTabBtnBg.setFillStyle(0x1144bb).setStrokeStyle(1.5, 0x4488ff);
   353→      this.wpTabLabel.setColor('#ffffff');
   354→      this.charTabBtnBg.setFillStyle(0x222222).setStrokeStyle(1.5, 0x555555);
   355→      this.charTabLabel.setColor('#888888');
   356→
   357→      this.buildWallpaperGrid();
   358→
   359→      // 헤더 텍스트 갱신
   360→      const selWpDef = this.selectedWpId
   361→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   362→        : null;
   363→      this.headerNameText
   364→        .setText(`배경: ${selWpDef?.name ?? '기본'}`)
   365→        .setColor(this.selectedWpId ? WP_ACCENT_HEX : '#888888');
   366→    }
   367→  }
   368→
   369→  /** 현재 탭에 맞게 배경 이미지 업데이트 */
   370→  private updateBgForTab() {
   371→    if (this.activeTab === 'character') {
   372→      const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   373→      this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   374→    } else {
   375→      const wpDef = this.selectedWpId
   376→        ? WALLPAPERS.find(w => w.id === this.selectedWpId)
   377→        : null;
   378→      if (wpDef && this.textures.exists(wpDef.bgKey)) {
   379→        this.bgImage.setTexture(wpDef.bgKey).setDisplaySize(400, 600).setAlpha(1).clearTint();
   380→      } else {
   381→        // 선택 배경 없음 → 캐릭터 일러스트를 어둡게 처리
   382→        const def = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   383→        this.bgImage.setTexture(def.illustKey).setDisplaySize(400, 600).setAlpha(0.2);
   384→      }
   385→    }
   386→  }
   387→
   388→  /** 서버 동기화 후 현재 탭을 내용 갱신 */
   389→  private rebuildGrid() {
   390→    this.cardsContainer.removeAll(true);
   391→    this.cardHighlights.clear();
   392→    this.wpHighlights.clear();
   393→    if (this.activeTab === 'character') {
   394→      this.buildCharacterGrid();
   395→    } else {
   396→      this.buildWallpaperGrid();
   397→    }
   398→  }
