   531→        applyBg.on('pointerout',  () => applyBg.setFillStyle(0x115511));
   532→        applyBg.on('pointerup',   () => this.applyWallpaper(def.id));
   533→        panel.add(applyBg);
   534→        panel.add(this.add.text(108, BTN_Y, '✔  적용하기', {
   535→          fontSize: '14px', color: '#88ff88', fontStyle: 'bold',
   536→        }).setOrigin(0.5));
   537→      } else {
   538→        // [해제]
   539→        const removeBg = this.add.rectangle(108, BTN_Y, BTN_W, BTN_H, 0x331111)
   540→          .setStrokeStyle(2, 0x884444)
   541→          .setInteractive({ useHandCursor: true });
   542→        removeBg.on('pointerover', () => removeBg.setFillStyle(0x442222));
   543→        removeBg.on('pointerout',  () => removeBg.setFillStyle(0x331111));
   544→        removeBg.on('pointerup',   () => this.applyWallpaper(null));
