   141→// ── localStorage 서명 (djb2, character.ts 패턴과 동일) ──────────────────────
   142→
   143→const OWNED_WP_KEY     = 'ownedWallpapers';
   144→const OWNED_WP_SIG_KEY = 'ownedWallpapersSig';
   145→const SELECTED_WP_KEY  = 'selectedWallpaper';
   146→const _WP_SALT         = 'ddong-wp-\u0076\u0031';
   147→
   148→function _signWpList(list: string[]): string {
   149→  const str = [...list].sort().join(',') + _WP_SALT;
   150→  let h = 5381;
   151→  for (let i = 0; i < str.length; i++) h = (((h << 5) + h) ^ str.charCodeAt(i)) >>> 0;
   152→  return h.toString(36);
   153→}
   154→
   155→function _saveOwnedWp(list: string[]): void {
   156→  localStorage.setItem(OWNED_WP_KEY, JSON.stringify(list));
   157→  localStorage.setItem(OWNED_WP_SIG_KEY, _signWpList(list));
   158→}
   159→
   160→/** 보유 배경화면 목록 반환. 서명 불일치 시 변조로 판단하여 빈 배열로 초기화. */
   161→export function getOwnedWallpapers(): string[] {
   162→  try {
   163→    const raw = localStorage.getItem(OWNED_WP_KEY);
   164→    const sig = localStorage.getItem(OWNED_WP_SIG_KEY);
   165→    const list: string[] = raw ? JSON.parse(raw) : [];
   166→
   167→    if (sig === null) {
   168→      // 서명 미존재 → 기존 데이터 마이그레이션: 신뢰 후 서명 최초 발급
   169→      _saveOwnedWp(list);
   170→    } else if (sig !== _signWpList(list)) {
   171→      // 서명 불일치 → 변조로 판단, 빈 배열로 초기화
   172→      _saveOwnedWp([]);
   173→      list.length = 0;
   174→    }
   175→
   176→    // 기본 배경은 항상 보유 (서명 저장 데이터에는 포함 안 됨, 읽기 시점에만 병합)
   177→    for (const id of DEFAULT_WP_IDS) {
   178→      if (!list.includes(id)) list.push(id);
   179→    }
   180→    return list;
   181→  } catch {
   182→    return [...DEFAULT_WP_IDS];
   183→  }
   184→}
   185→
   186→/** 서버 동기화 등 외부에서 목록 전체를 덮어쓸 때 사용 (서명 함께 갱신) */
   187→export function setOwnedWallpapers(list: string[]): void {
   188→  _saveOwnedWp(list);
   189→}
   190→
   191→/** 배경화면을 보유 목록에 추가 (가챠 완료 직후 호출) */
   192→export function addOwnedWallpaper(id: string): void {
   193→  const owned = getOwnedWallpapers();
   194→  if (!owned.includes(id)) {
   195→    owned.push(id);
   196→    _saveOwnedWp(owned);
   197→  }
   198→}
   199→
   200→/** 선택된 배경화면 ID 반환. 없으면 null (기본 배경 사용). */
   201→export function getSelectedWallpaper(): string | null {
   202→  return localStorage.getItem(SELECTED_WP_KEY);
   203→}
   204→
   205→/** 배경화면 선택 저장. null 전달 시 선택 해제. */
   206→export function setSelectedWallpaper(id: string | null): void {
   207→  if (id === null) {
   208→    localStorage.removeItem(SELECTED_WP_KEY);
   209→  } else {
   210→    localStorage.setItem(SELECTED_WP_KEY, id);
   211→  }
   212→}
   213→
   214→/**
   215→ * 보유 목록과 교차 검증하여 안전한 배경화면 ID 반환.
   216→ * 미보유 배경이 선택되어 있으면 null로 강제 초기화 (변조 방지).
   217→ */
   218→export function getSafeSelectedWallpaper(): string | null {
   219→  const selected = getSelectedWallpaper();
   220→  if (!selected) return null;
   221→  const owned = getOwnedWallpapers();
   222→  if (owned.includes(selected)) return selected;
   223→  // 변조 감지 → null로 강제 초기화
   224→  setSelectedWallpaper(null);
   225→  return null;
   226→}
   227→
   228→/** 배경화면 정의 조회. 없으면 undefined. */
   229→export function getWallpaperDef(id: string): BackgroundDef | undefined {
   230→  return WALLPAPERS.find(w => w.id === id);
   231→}
