   123→  create() {
   124→    this.selectedId = getSelectedCharacter();
   125→    this.ownedIds = getOwnedCharacters();
   126→    this.ownedWpIds = getOwnedWallpapers();
   127→    this.selectedWpId = getSelectedWallpaper();
   128→    this.activeTab = 'character';
   129→    this.scrollOffset = 0;
   130→    this.hasDragged = false;
   131→    this.hasPointerDownInScene = false;
   132→    this.cardHighlights.clear();
   133→    this.wpHighlights.clear();
   134→
   135→    // 동기화 전 각성 수치 스냅샷 (동기화 후 변화 감지용)
   136→    this._preSyncDupCounts = new Map(
   137→      CHARACTERS
   138→        .filter(c => this.ownedIds.includes(c.id) && c.grade !== '등급외')
   139→        .map(c => [c.id, getDuplicateCount(c.id)])
   140→    );
   141→
   142→    // 서버 DB와 동기화 — 소유 목록 or 각성 수치가 바뀐 경우 씬 재시작해서 카드 갱신
   143→    syncOwnedCharacters().then(synced => {
   144→      if (!this.scene.isActive()) return;
   145→      const ownedChanged = synced.length !== this.ownedIds.length ||
   146→        synced.some(id => !this.ownedIds.includes(id));
   147→      const awakeChanged = CHARACTERS.some(c =>
   148→        synced.includes(c.id) && c.grade !== '등급외' &&
   149→        getDuplicateCount(c.id) !== this._preSyncDupCounts.get(c.id)
   150→      );
   151→      if (ownedChanged || awakeChanged) this.scene.restart();
   152→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
   153→
   154→    // 배경화면 동기화 (비동기, UI 갱신 없이 진행 — 다음 방문 시 반영)
   155→    syncOwnedWallpapers().then(synced => {
   156→      if (!this.scene.isActive()) return;
   157→      const wpChanged = synced.length !== this.ownedWpIds.length ||
   158→        synced.some(id => !this.ownedWpIds.includes(id));
   159→      if (wpChanged && this.activeTab === 'wallpaper') this.rebuildGrid();
   160→    }).catch(() => { /* 네트워크 오류 시 로컬 상태 유지 */ });
   161→
   162→    const selectedDef = CHARACTERS.find(c => c.id === this.selectedId) ?? CHARACTERS[0];
   163→
   164→    // ── 배경: 선택된 캐릭터 일러스트 ───────────────────────────────────
   165→    this.bgImage = this.add.image(200, 300, selectedDef.illustKey);
   166→    this.bgImage.setDisplaySize(400, 600);
   167→
   168→    // ── 헤더 (고정) ─────────────────────────────────────────────────────
   169→    this.add.text(200, 30, '수집', {
   170→      fontSize: '22px',
   171→      color: '#ffffff',
   172→      fontStyle: 'bold',
   173→      stroke: '#000',
   174→      strokeThickness: 4,
   175→    }).setOrigin(0.5);
   176→
   177→    // ── 탭 버튼 ────────────────────────────────────────────────────────
   178→    const TAB_Y = 60;
   179→    const TAB_W = 160;
   180→    const TAB_H = 30;
   181→
   182→    this.charTabBtnBg = this.add.rectangle(110, TAB_Y, TAB_W, TAB_H, 0x1144bb)
   183→      .setStrokeStyle(1.5, 0x4488ff)
   184→      .setInteractive({ useHandCursor: true });
   185→    this.charTabLabel = this.add.text(110, TAB_Y, '캐릭터', {
   186→      fontSize: '14px', color: '#ffffff', fontStyle: 'bold',
   187→    }).setOrigin(0.5);
   188→
   189→    this.wpTabBtnBg = this.add.rectangle(290, TAB_Y, TAB_W, TAB_H, 0x222222)
   190→      .setStrokeStyle(1.5, 0x555555)
   191→      .setInteractive({ useHandCursor: true });
   192→    this.wpTabLabel = this.add.text(290, TAB_Y, '배경화면', {
   193→      fontSize: '14px', color: '#888888', fontStyle: 'bold',
   194→    }).setOrigin(0.5);
   195→
   196→    this.charTabBtnBg.on('pointerup', () => {
   197→      if (this.detailPanel) return;
   198→      this.switchTab('character');
   199→    });
   200→    this.wpTabBtnBg.on('pointerup', () => {
   201→      if (this.detailPanel) return;
   202→      this.switchTab('wallpaper');
   203→    });
   204→
   205→    // 구분선
   206→    this.add.rectangle(200, 80, 380, 1, 0x444444);
   207→
   208→    // 현재 선택 상태 표시
   209→    this.headerNameText = this.add.text(200, 88, `현재: ${selectedDef.name}`, {
   210→      fontSize: '13px',
   211→      color: selectedDef.gradeColor,
   212→      stroke: '#000',
   213→      strokeThickness: 3,
   214→    }).setOrigin(0.5);
   215→
   216→    // ── 스크롤 가능한 카드 컨테이너 ─────────────────────────────────────
   217→    this.cardsContainer = this.add.container(0, 0);
   218→
   219→    this.buildCharacterGrid();
   220→
   221→    // 스크롤 최대 범위 계산 (buildCharacterGrid 내부에서도 설정되지만 여기서도 초기화)
   222→    const totalRows = Math.ceil(CHARACTERS.length / COLS);
   223→    const contentBottom = GRID_TOP + (totalRows - 1) * (CARD_H + GAP_Y) + CARD_H + 10;
   224→    this.maxScrollOffset = Math.max(0, contentBottom - SCROLL_BOTTOM);
   225→
   226→    // 카드 영역 마스크 (스크롤 영역 밖 숨김)
   227→    // this.make: display list에 추가되지 않으므로 shutdown 시 직접 정리 필요
   228→    this.maskGfx = this.make.graphics({ x: 0, y: 0 });
   229→    this.maskGfx.fillStyle(0xffffff);
   230→    this.maskGfx.fillRect(0, SCROLL_TOP, 400, SCROLL_BOTTOM - SCROLL_TOP);
   231→    this.cardsContainer.setMask(this.maskGfx.createGeometryMask());
   232→
   233→    // ── 드래그 스크롤 입력 ───────────────────────────────────────────────
   234→    this.input.on('pointerdown', (p: Phaser.Input.Pointer) => {
   235→      this.hasPointerDownInScene = true;
   236→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   237→      if (p.y < SCROLL_TOP || p.y > SCROLL_BOTTOM) return;
   238→      this.pointerDownY = p.y;
   239→      this.pointerDownScrollY = this.scrollOffset;
   240→      this.hasDragged = false;
   241→    });
   242→
   243→    this.input.on('pointermove', (p: Phaser.Input.Pointer) => {
   244→      if (this.detailPanel) return; // 상세 패널 열려있으면 스크롤 무시
   245→      if (!p.isDown) return;
   246→      const dy = this.pointerDownY - p.y;
   247→      if (Math.abs(dy) > 5) {
   248→        this.hasDragged = true;
   249→        this.scrollOffset = Phaser.Math.Clamp(
   250→          this.pointerDownScrollY + dy,
   251→          0,
   252→          this.maxScrollOffset,
   253→        );
   254→        this.cardsContainer.setY(-this.scrollOffset);
   255→      }
   256→    });
   257→
   258→    this.input.on('pointerup', () => {
   259→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
   260→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
   261→      this.time.delayedCall(0, () => {
   262→        this.hasDragged = false;
   263→        this.hasPointerDownInScene = false;
   264→      });
   265→    });
   266→
   267→    // 마우스 휠
   268→    this.input.on(
   269→      'wheel',
   270→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
   271→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
   272→        this.scrollOffset = Phaser.Math.Clamp(
   273→          this.scrollOffset + deltaY * 0.5,
   274→          0,
   275→          this.maxScrollOffset,
   276→        );
   277→        this.cardsContainer.setY(-this.scrollOffset);
   278→      },
   279→    );
   280→
   281→    // ── 고정 UI ─────────────────────────────────────────────────────────
   282→    this.createBackButton();
   283→
   284→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
   285→    this.events.once('shutdown', () => { this.maskGfx.destroy(); });
   286→  }
