   388→  /** 서버 동기화 후 현재 탭을 내용 갱신 */
   389→  private rebuildGrid() {
   390→    this.cardsContainer.removeAll(true);
   391→    this.cardHighlights.clear();
   392→    this.wpHighlights.clear();
   393→    if (this.activeTab === 'character') {
   394→      this.buildCharacterGrid();
   395→    } else {
   396→      this.buildWallpaperGrid();
   397→    }
   398→  }
