   400→  // ── 배경화면 카드 ────────────────────────────────────────────────────────
   401→
   402→  private createWallpaperCard(wp: BackgroundDef, x: number, y: number) {
   403→    const isOwned = this.ownedWpIds.includes(wp.id);
   404→    const isSelected = this.selectedWpId === wp.id;
   405→
   406→    // 카드 배경
   407→    const cardBg = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0x1a1a2e);
   408→    cardBg.setStrokeStyle(2, isOwned ? WP_ACCENT_INT : 0x333333);
   409→    this.cardsContainer.add(cardBg);
   410→
   411→    // 선택 하이라이트 (흰 테두리)
   412→    const highlight = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0, 0);
   413→    highlight.setStrokeStyle(3, 0xffffff);
   414→    highlight.setVisible(isSelected);
   415→    this.wpHighlights.set(wp.id, highlight);
   416→    this.cardsContainer.add(highlight);
   417→
   418→    // 세로 이미지 (bgKey) — 카드 상단을 채우는 portrait 썸네일
   419→    if (this.textures.exists(wp.bgKey)) {
   420→      const thumb = this.add.image(x, y - 11, wp.bgKey)
   421→        .setDisplaySize(WP_CARD_W - 4, WP_CARD_H - 22);
   422→      if (!isOwned) { thumb.setTint(0x000000); thumb.setAlpha(0.5); }
   423→      this.cardsContainer.add(thumb);
   424→    }
   425→
   426→    // 미보유 자물쇠
   427→    if (!isOwned) {
   428→      const lock = this.add.text(x, y - 8, '🔒', { fontSize: '20px' }).setOrigin(0.5);
   429→      this.cardsContainer.add(lock);
   430→    }
   431→
   432→    // WP 배지 (우상단) — 기본 배경은 '기본', 가챠 배경은 'WP'
   433→    const isDefault = (DEFAULT_WP_IDS as readonly string[]).includes(wp.id);
   434→    const badgeText  = isDefault ? '기본' : 'WP';
   435→    const badgeColor = isDefault ? '#aaaaaa' : WP_ACCENT_HEX;
   436→    const badge = this.add.text(x + WP_CARD_W / 2 - 2, y - WP_CARD_H / 2 + 2, badgeText, {
   437→      fontSize: '9px', color: badgeColor, fontStyle: 'bold',
   438→      backgroundColor: '#000000cc', padding: { x: 3, y: 1 },
   439→    }).setOrigin(1, 0);
   440→    this.cardsContainer.add(badge);
   441→
   442→    // 하단 반투명 바 + 이름
   443→    const barY = y + WP_CARD_H / 2 - 11;
   444→    const bar = this.add.rectangle(x, barY, WP_CARD_W, 22, 0x000000, 0.75);
   445→    this.cardsContainer.add(bar);
   446→    const nameText = this.add.text(x, barY, wp.name, {
   447→      fontSize: '11px',
   448→      color: isOwned ? WP_ACCENT_HEX : '#444444',
   449→      fontStyle: 'bold',
   450→    }).setOrigin(0.5);
   451→    this.cardsContainer.add(nameText);
   452→
   453→    // 클릭 이벤트
   454→    cardBg.setInteractive({ useHandCursor: isOwned });
   455→    if (isOwned) {
   456→      cardBg.on('pointerover', () => cardBg.setFillStyle(0x252540));
   457→      cardBg.on('pointerout',  () => cardBg.setFillStyle(0x1a1a2e));
   458→    }
   459→    cardBg.on('pointerup', () => {
   460→      if (!this.hasDragged && this.hasPointerDownInScene) this.showWallpaperDetail(wp);
   461→    });
   462→  }
