   518→
   519→    // ── 버튼 2개 ──
   520→    const BTN_Y = 562;
   521→    const BTN_W = 168;
   522→    const BTN_H = 42;
   523→
   524→    if (isOwned) {
   525→      if (!isSelected) {
   526→        // [적용하기]
   527→        const applyBg = this.add.rectangle(108, BTN_Y, BTN_W, BTN_H, 0x115511)
