   593→  private createCharacterCard(char: CharacterDef, x: number, y: number) {
   594→    const isOwned = this.ownedIds.includes(char.id);
   595→    const isSelected = this.selectedId === char.id;
   596→    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);
   597→
   598→    // 카드 배경
   599→    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
   600→    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
   601→    this.cardsContainer.add(cardBg);
   602→
   603→    // 선택 하이라이트
   604→    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
   605→    highlight.setStrokeStyle(3, 0xffffff);
   606→    highlight.setVisible(isSelected);
   607→    this.cardHighlights.set(char.id, highlight);
   608→    this.cardsContainer.add(highlight);
   609→
   610→    // 캐릭터 이미지
   611→    const img = this.add.image(x, y - 12, char.imageKey);
   612→    img.setDisplaySize(58, 85);
   613→    this.cardsContainer.add(img);
   614→
   615→    if (!isOwned) {
   616→      img.setTint(0x000000);
   617→      img.setAlpha(0.6);
   618→      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
   619→      this.cardsContainer.add(lock);
   620→    }
   621→
   622→    // 등급 배지
   623→    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
   624→      fontSize: '9px',
   625→      color: char.gradeColor,
   626→      fontStyle: 'bold',
   627→      backgroundColor: '#000000cc',
   628→      padding: { x: 3, y: 1 },
   629→    }).setOrigin(1, 0);
   630→    this.cardsContainer.add(badge);
   631→
   632→    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
   633→    if (isOwned && char.grade !== '등급외') {
   634→      const dupCount   = getDuplicateCount(char.id);
   635→      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
   636→      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;
   637→
   638→      for (let i = 0; i < CORE_COUNT; i++) {
   639→        const cx = x + (i - 2) * CORE_GAP;
   640→        if (i < awakeLevel) {
   641→          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
   642→          this.coresGfx.fillStyle(gradeColorInt, 0.25);
   643→          this.coresGfx.fillCircle(cx, coreY, CORE_GLOW_RADIUS);
   644→          this.coresGfx.fillStyle(gradeColorInt, 1);
   645→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   646→          this.coresGfx.fillStyle(0xffffff, 0.55);
   647→          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
   648→        } else {
   649→          // 빈 코어: 어두운 원 + 얇은 테두리
   650→          this.coresGfx.fillStyle(0x111111, 1);
   651→          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
   652→          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
   653→          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
   654→        }
   655→      }
   656→    }
   657→
   658→    // 캐릭터 이름
   659→    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
   660→      fontSize: '12px',
   661→      color: isOwned ? '#ffffff' : '#555555',
   662→      fontStyle: 'bold',
   663→    }).setOrigin(0.5);
   664→    this.cardsContainer.add(nameText);
   665→
   666→    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
   667→    cardBg.setInteractive({ useHandCursor: isOwned });
   668→
   669→    if (isOwned) {
   670→      cardBg.on('pointerover', () => {
   671→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
   672→      });
   673→      cardBg.on('pointerout', () => {
   674→        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
   675→      });
   676→    }
   677→    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
   678→    cardBg.on('pointerup', () => {
   679→      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
   680→    });
   681→  }
