   840→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
   841→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
   842→    const W = 400, H = 600;
   843→    vid.setDisplaySize(W, H);
   844→
   845→    const applyContain = () => {
   846→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   847→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
   848→      const nw = el?.videoWidth  || 0;
   849→      const nh = el?.videoHeight || 0;
   850→      if (nw > 0 && nh > 0) {
   851→        const scale = Math.max(W / nw, H / nh);
   852→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
   853→      }
   854→    };
   855→
   856→    vid.once('play', applyContain);
   857→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
   858→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
   859→  }
   860→
   861→  private hideCharacterDetail(): void {
   862→    // fitVideoToPanel의 pending 타이머 취소
   863→    for (const t of this.fitVideoTimers) t.remove();
   864→    this.fitVideoTimers = [];
   865→
   866→    // 비디오 명시 정지 및 HTMLVideoElement src 해제
   867→    if (this.detailVideo) {
   868→      this.detailVideo.stop();
   869→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
   870→      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
   871→      if (el) { el.src = ''; }
   872→      this.detailVideo = null;
   873→    }
   874→
   875→    this.hideInfoPanel();
   876→    this.detailPanel?.destroy();
   877→    this.detailPanel = null;
   878→  }
