   888→    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
   889→    const panel = this.add.container(0, 0).setDepth(400);
   890→    this.infoPanel = panel;
   891→
   892→    // ── 각성 보너스 계산 ──────────────────────────────────────────────
   893→    const dupCount   = getDuplicateCount(def.id);
   894→    const awakeLevel = getAwakeningLevel(def.grade, dupCount);
   895→    const awakeBonusLines: string[] = [];
   896→    if (def.grade !== '등급외') {
   897→      if (awakeLevel >= 1) {
   898→        const spd = def.id === 'maehwa' ? 5 : def.grade === 'UR' ? 15 : def.grade === 'SR' ? 10 : 5;
   899→        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
   900→      }
   901→      if (awakeLevel >= 2) {
   902→        if (def.id === 'maehwa') {
   903→          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
   904→        } else {
   905→          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
   906→          awakeBonusLines.push(`★2 각성: 이동속도 +${spd} px/s (누적)`);
   907→        }
   908→      }
   909→    }
   910→    const awakeBonusText = awakeBonusLines.join('\n');
   911→
   912→    // 반투명 배경 (클릭 시 닫기)
   913→    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.80)
   914→      .setInteractive();
   915→    overlay.on('pointerup', () => this.hideInfoPanel());
   916→    panel.add(overlay);
   917→
   918→    // ── 카드 크기 계산 (텍스트 높이 선측정) ─────────────────────────
   919→    const B_LEFT = 30;
   920→    const CARD_W = 370;
   921→    const WRAP_W = CARD_W - 40; // 좌(15px)·우(25px) 여백 제외한 실제 텍스트 폭
   922→    const HEADER_H = 60;  // 스프라이트+이름+구분선 영역
   923→    const PAD_BOT  = 20;
   924→
   925→    const btMeasure = this.add.text(0, -999, def.basicEffect,    { fontSize: '13px', wordWrap: { width: WRAP_W } });
   926→    const stMeasure = this.add.text(0, -999, def.specialAbility, { fontSize: '13px', wordWrap: { width: WRAP_W } });
   927→    const abMeasure = awakeBonusText
   928→      ? this.add.text(0, -999, awakeBonusText, { fontSize: '12px', wordWrap: { width: WRAP_W } })
