   570→  private showNextReveal() {
   571→    if (this.revealItemIndex >= this.revealItems.length) {
   572→      this.showSummary();
   573→      return;
   574→    }
   575→
   576→    const item = this.revealItems[this.revealItemIndex];
   577→
   578→    // 배경화면 슬롯이면 배경 리빌 카드로 분기
   579→    if (item.kind === 'wallpaper') {
   580→      const def = WALLPAPERS.find(w => w.id === item.data.id);
   581→      this.showWallpaperRevealCard(item.data, def);
   582→      return;
   583→    }
   584→
   585→    const pulled = item.data;
   586→    const def = getCharacterDef(pulled.id);
   587→
   588→    const { width, height } = this.cameras.main;
   589→    this.clearUI();
   590→
   591→    const vidKey = `vid_${pulled.id}`;
   592→    if (this.cache.video.exists(vidKey)) {
   593→      const vid = this.add.video(width / 2, height / 2, vidKey);
   594→      vid.play(false);
   595→      this.fitVideoToCanvas(vid, width, height);
   596→
   597→      let proceeded = false;
   598→      const proceed = () => {
   599→        if (proceeded) return;
   600→        proceeded = true;
   601→        this.input.off('pointerdown', proceed);
   602→        if (vid.active) vid.destroy();
   603→        this.showRevealCard(pulled, def);
   604→      };
   605→
   606→      this.addSkipButton(() => {
   607→        if (proceeded) return;
   608→        proceeded = true;
   609→        this.input.off('pointerdown', proceed);
   610→        if (vid.active) vid.destroy();
   611→        // 10연차: 영상 스킵 시 남은 리빌 전체 건너뛰고 결과 화면으로
   612→        if (this.revealItems.length > 1) {
   613→          this.showSummary();
   614→        } else {
   615→          this.showRevealCard(pulled, def);
   616→        }
   617→      });
   618→      vid.on('complete', proceed);
   619→      this.time.delayedCall(10000, proceed); // failsafe
   620→      this.input.once('pointerdown', proceed); // 탭으로 스킵
   621→    } else {
   622→      this.showRevealCard(pulled, def);
   623→    }
   624→  }
