   742→  private showSummary() {
   743→    this.clearUI();
   744→    if (this.textures.exists('gacha_background')) {
   745→      this.add.image(200, 300, 'gacha_background').setDisplaySize(400, 600);
   746→    } else {
   747→      this.add.rectangle(200, 300, 400, 600, 0x060612);
   748→    }
   749→    this.add.rectangle(200, 300, 400, 600, 0x000000, 0.55);
   750→
   751→    this.add.text(200, 38, '[ EXTRACTION COMPLETE ]', {
   752→      fontSize: '17px', color: '#00ff41', fontStyle: 'bold', fontFamily: 'monospace',
   753→    }).setOrigin(0.5);
   754→
   755→    // ── 캐릭터 + 배경화면 통합 그리드 ───────────────────────────────
   756→    const charCount = this.pullResults.length;
   757→    const wpCount = this.wpResults.length;
   758→    const total = charCount + wpCount;
   759→    const cols = Math.min(total, 5);
   760→    const cardW = 64, cardH = 84, gapX = 8, gapY = 12;
   761→    const totalW = cols * cardW + (cols - 1) * gapX;
   762→    const startX = (400 - totalW) / 2 + cardW / 2;
   763→    const startY = total > 5 ? 130 : 175;
   764→
   765→    // 캐릭터 카드
   766→    this.pullResults.forEach((pulled, i) => {
   767→      const def = getCharacterDef(pulled.id);
   768→      const col = i % 5;
   769→      const row = Math.floor(i / 5);
   770→      const x = startX + col * (cardW + gapX);
