   901→  private typeLine(text: string, charDelay = 40, color = '#00ff41'): Promise<void> {
   902→    return new Promise(resolve => {
   903→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   904→
   905→      // 최대 6줄 유지 (스크롤 효과)
   906→      if (this.terminalTexts.length >= 6) {
   907→        this.terminalTexts.shift()?.destroy();
   908→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   909→      }
   910→
   911→      const y = 276 + this.terminalTexts.length * 22;
   912→      const t = this.add.text(24, y, '', {
   913→        fontSize: '13px', color, fontFamily: 'monospace',
   914→      });
   915→      this.terminalTexts.push(t);
   916→
   917→      let i = 0;
   918→      const ev = this.time.addEvent({
   919→        delay: charDelay,
   920→        repeat: text.length,
   921→        callback: () => {
   922→          if (!this.scene.isActive() || this.skipTerminal) { ev.destroy(); resolve(); return; }
   923→          t.setText(text.substring(0, i + 1));
   924→          i++;
   925→          if (i > text.length) { ev.destroy(); resolve(); }
   926→        },
   927→      });
   928→    });
   929→  }
