   932→    return new Promise(resolve => {
   933→      if (!this.scene.isActive() || this.skipTerminal) { resolve(); return; }
   934→
   935→      if (this.terminalTexts.length >= 6) {
   936→        this.terminalTexts.shift()?.destroy();
   937→        this.terminalTexts.forEach((t, i) => t.setY(276 + i * 22));
   938→      }
   939→
   940→      const y = 276 + this.terminalTexts.length * 22;
   941→      const bar = this.add.text(24, y, '> [          ]  0%', {
   942→        fontSize: '13px', color, fontFamily: 'monospace',
   943→      });
   944→      this.terminalTexts.push(bar);
   945→
   946→      let step = 0;
   947→      const steps = 10;
   948→      const ev = this.time.addEvent({
   949→        delay: duration / steps,
   950→        repeat: steps - 1,
   951→        callback: () => {
   952→          step++;
   953→          bar.setText(`> [${'█'.repeat(step)}${' '.repeat(steps - step)}] ${step * 10}%`);
   954→          if (this.skipTerminal || step >= steps) { ev.destroy(); resolve(); }
   955→        },
   956→      });
   957→    });
   958→  }
