     1→import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';
     2→
     3→const corsHeaders = {
     4→  'Access-Control-Allow-Origin': '*',
     5→  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
     6→};
     7→
     8→// ── 배경화면 풀 정의 ─────────────────────────────────────────────────────
     9→// 등급 없음. 10종 균등 확률.
    10→// 뽑기당 드롭율 3.5% → 종당 실효 확률 0.35% (캐릭터 UR과 동일 수준)
    11→const WP_DROP_CHANCE = 0.035; // 슬롯당 3.5% → 종당 실효 확률 약 1.17%
    12→const WP_POOL = [
    13→  { id: 'wp_hanok'  },
    14→  { id: 'wp_lake'   },
    15→  { id: 'wp_maehwa' },
    16→];
    17→
    18→function pullWallpaper(): { id: string } {
    19→  return WP_POOL[Math.floor(Math.random() * WP_POOL.length)];
    20→}
    21→
    22→// ── 뽑기 풀 정의 ────────────────────────────────────────────────────────
    23→// R 80% (10종 균등 배분), SR 19.3% (6종 균등 배분), UR 0.7% (2종 균등 배분)
    24→const SR_W  = 19.3 / 6;   // ≈ 3.217%
    25→const POOL = [
    26→  // ── R등급 ──
    27→  { id: 'log',     grade: 'R',  weight: 8 },
    28→  { id: 'swap',    grade: 'R',  weight: 8 },
    29→  { id: 'sum',     grade: 'R',  weight: 8 },
    30→  { id: 'fork',    grade: 'R',  weight: 8 },
    31→  { id: 'seed',    grade: 'R',  weight: 8 },
    32→  { id: 'session', grade: 'R',  weight: 8 },
    33→  { id: 'branch',  grade: 'R',  weight: 8 },
    34→  { id: 'hook',    grade: 'R',  weight: 8 },
    35→  { id: 'socket',  grade: 'R',  weight: 8 },
    36→  { id: 'index',   grade: 'R',  weight: 8 },
    37→  // ── SR등급 ──
    38→  { id: 'hacker',   grade: 'SR', weight: SR_W },
    39→  { id: 'miner',    grade: 'SR', weight: SR_W },
    40→  { id: 'maehwa',   grade: 'SR', weight: SR_W },
    41→  { id: 'archieve', grade: 'SR', weight: SR_W },
    42→  { id: 'glitch',   grade: 'SR', weight: SR_W },
    43→  { id: 'noise',    grade: 'SR', weight: SR_W },
    44→  // ── UR등급 ──
    45→  { id: 'sentinel', grade: 'UR', weight: 0.35 },
    46→  { id: 'legacy',   grade: 'UR', weight: 0.35 },
    47→];
    48→
    49→function pullOne(): { id: string; grade: string } {
    50→  const total = POOL.reduce((s, c) => s + c.weight, 0);
    51→  let r = Math.random() * total;
    52→  for (const c of POOL) {
    53→    r -= c.weight;
    54→    if (r <= 0) return { id: c.id, grade: c.grade };
    55→  }
    56→  return { id: POOL[POOL.length - 1].id, grade: POOL[POOL.length - 1].grade };
    57→}
    58→
    59→// ── 요청 처리 ───────────────────────────────────────────────────────────
    60→Deno.serve(async (req: Request) => {
    61→  if (req.method === 'OPTIONS') {
    62→    return new Response('ok', { headers: corsHeaders });
    63→  }
    64→
    65→  try {
    66→    const { pullType } = await req.json(); // 'single' | 'multi'
    67→
    68→    if (pullType !== 'single' && pullType !== 'multi') {
    69→      return new Response(
    70→        JSON.stringify({ error: 'Invalid pullType' }),
    71→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    72→      );
    73→    }
    74→
    75→    const cost = pullType === 'multi' ? 900 : 100;
    76→    const count = pullType === 'multi' ? 10 : 1;
    77→
    78→    // 인증
    79→    const authHeader = req.headers.get('Authorization');
    80→    if (!authHeader) {
    81→      return new Response(
    82→        JSON.stringify({ error: 'Missing authorization header' }),
    83→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    84→      );
    85→    }
    86→
    87→    const supabaseUser = createClient(
    88→      Deno.env.get('SUPABASE_URL') ?? '',
    89→      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
    90→      { global: { headers: { Authorization: authHeader } } }
    91→    );
    92→
    93→    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    94→    if (authError || !user) {
    95→      return new Response(
    96→        JSON.stringify({ error: 'Unauthorized' }),
    97→        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    98→      );
    99→    }
   100→
   101→    const supabaseAdmin = createClient(
   102→      Deno.env.get('SUPABASE_URL') ?? '',
   103→      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
   104→    );
   105→
   106→    // ── 1. SKOR 잔액 + 보유 캐릭터 + 보유 배경화면 병렬 조회 ────────
   107→    const [{ data: skorData }, { data: owned }, { data: ownedWp }] = await Promise.all([
   108→      supabaseAdmin.from('user_skor').select('balance').eq('user_id', user.id).single(),
   109→      supabaseAdmin.from('user_characters').select('character_id').eq('user_id', user.id),
   110→      supabaseAdmin.from('user_wallpapers').select('wallpaper_id').eq('user_id', user.id),
   111→    ]);
   112→
   113→    const balance = skorData?.balance ?? 0;
   114→    if (balance < cost) {
   115→      return new Response(
   116→        JSON.stringify({ error: 'Insufficient SKOR', balance }),
   117→        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
   118→      );
   119→    }
   120→
   121→    // ── 2. 슬롯별 결정: 각 슬롯은 배경화면 또는 캐릭터 중 하나
   122→    //       총합 = count, 추가 드롭 없음 ────────────────────────────────
   123→    const ownedSet = new Set((owned ?? []).map((r: { character_id: string }) => r.character_id));
   124→    const ownedWpSet = new Set((ownedWp ?? []).map((r: { wallpaper_id: string }) => r.wallpaper_id));
   125→
   126→    const characters: { id: string; grade: string; isNew: boolean }[] = [];
   127→    const wallpapers: { id: string; isNew: boolean }[] = [];
   128→
   129→    for (let i = 0; i < count; i++) {
   130→      if (Math.random() < WP_DROP_CHANCE) {
   131→        // 이 슬롯은 배경화면
   132→        const wp = pullWallpaper();
   133→        wallpapers.push({ id: wp.id, isNew: !ownedWpSet.has(wp.id) });
   134→        ownedWpSet.add(wp.id); // 같은 pull 내 중복 isNew 방지
   135→      } else {
   136→        // 이 슬롯은 캐릭터
   137→        const char = pullOne();
   138→        characters.push({ id: char.id, grade: char.grade, isNew: !ownedSet.has(char.id) });
   139→      }
