private updateTabUI() {
  const isChar = this.activeTab === 'character';

  this.charTabBtnBg.setFillStyle(isChar ? 0x1144bb : 0x222222)
    .setStrokeStyle(1.5, isChar ? 0x4488ff : 0x555555);
