// 클래스 레벨에서 캐시 (GameScene처럼 씬 내 캐싱)
private wallpaperDefCache: Map<string, BackgroundDef | undefined> = new Map();

private getWallpaperDefCached(id: string): BackgroundDef | undefined {
  if (!this.wallpaperDefCache.has(id)) {
    this.wallpaperDefCache.set(id, WALLPAPERS.find(w => w.id === id));
  }
  return this.wallpaperDefCache.get(id);
}
```

