### 권장사항
```typescript
interface GridConfig {
  items: any[];
  cols: number;
  cardW: number;
  cardH: number;
  gapX: number;
  gapY: number;
  gridLeft: number;
  gridTop: number;
}

private calculateGridPosition(config: GridConfig, index: number): { x: number; y: number } {
  const col = index % config.cols;
  const row = Math.floor(index / config.cols);
  const x = config.gridLeft + col * (config.cardW + config.gapX) + config.cardW / 2;
  const y = config.gridTop + row * (config.cardH + config.gapY) + config.cardH / 2;
  return { x, y };
}

private calculateGridBottom(config: GridConfig): number {
  const totalRows = Math.ceil(config.items.length / config.cols);
  return config.gridTop + (totalRows - 1) * (config.cardH + config.gapY) + config.cardH + 10;
}
```

