    }));

    // ── 버튼 2개 ──
    const BTN_Y = 562;
    const BTN_W = 168;
    const BTN_H = 42;

    if (isOwned) {
      if (!isSelected) {
        // [적용하기]
        const applyBg = this.add.rectangle(108, BTN_Y, BTN_W, BTN_H, 0x115511)
