  private applyWallpaper(id: string | null) {
    setSelectedWallpaper(id);
    this.selectedWpId = id;

    // 하이라이트 갱신
    this.wpHighlights.forEach((rect, wpId) => {
      rect.setVisible(wpId === id);
    });

    // 헤더 텍스트 갱신
    const def = id ? WALLPAPERS.find(w => w.id === id) : null;
    this.headerNameText
      .setText(`배경: ${def?.name ?? '기본'}`)
      .setColor(id ? WP_ACCENT_HEX : '#888888');

    // 배경 이미지 즉시 반영
    this.updateBgForTab();

    this.hideCharacterDetail();
  }

  private createCharacterCard(char: CharacterDef, x: number, y: number) {
    const isOwned = this.ownedIds.includes(char.id);
    const isSelected = this.selectedId === char.id;
    const gradeColorInt = parseInt(char.gradeColor.replace('#', ''), 16);

    // 카드 배경
    const cardBg = this.add.rectangle(x, y, CARD_W, CARD_H, 0x222222);
    cardBg.setStrokeStyle(2, isOwned ? gradeColorInt : 0x444444);
    this.cardsContainer.add(cardBg);

    // 선택 하이라이트
    const highlight = this.add.rectangle(x, y, CARD_W, CARD_H, 0, 0);
    highlight.setStrokeStyle(3, 0xffffff);
    highlight.setVisible(isSelected);
    this.cardHighlights.set(char.id, highlight);
    this.cardsContainer.add(highlight);

    // 캐릭터 이미지
    const img = this.add.image(x, y - 12, char.imageKey);
    img.setDisplaySize(58, 85);
    this.cardsContainer.add(img);

    if (!isOwned) {
      img.setTint(0x000000);
      img.setAlpha(0.6);
      const lock = this.add.text(x, y - 12, '🔒', { fontSize: '22px' }).setOrigin(0.5);
      this.cardsContainer.add(lock);
    }

    // 등급 배지
    const badge = this.add.text(x + CARD_W / 2 - 2, y - CARD_H / 2 + 2, char.grade, {
      fontSize: '9px',
      color: char.gradeColor,
      fontStyle: 'bold',
      backgroundColor: '#000000cc',
      padding: { x: 3, y: 1 },
    }).setOrigin(1, 0);
    this.cardsContainer.add(badge);

    // 각성 코어 (등급외 제외, 보유 캐릭터만) — 공유 coresGfx에 직접 그림
    if (isOwned && char.grade !== '등급외') {
      const dupCount   = getDuplicateCount(char.id);
      const awakeLevel = getAwakeningLevel(char.grade, dupCount);
      const coreY      = y + CARD_H / 2 - CORE_Y_OFFSET;

      for (let i = 0; i < CORE_COUNT; i++) {
        const cx = x + (i - 2) * CORE_GAP;
        if (i < awakeLevel) {
          // 충전된 코어: 외곽 글로우 + 내부 밝은 원
          this.coresGfx.fillStyle(gradeColorInt, 0.25);
          this.coresGfx.fillCircle(cx, coreY, CORE_GLOW_RADIUS);
          this.coresGfx.fillStyle(gradeColorInt, 1);
          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
          this.coresGfx.fillStyle(0xffffff, 0.55);
          this.coresGfx.fillCircle(cx - 1, coreY - 1, CORE_HIGHLIGHT_R);
        } else {
          // 빈 코어: 어두운 원 + 얇은 테두리
          this.coresGfx.fillStyle(0x111111, 1);
          this.coresGfx.fillCircle(cx, coreY, CORE_INNER_RADIUS);
          this.coresGfx.lineStyle(1, gradeColorInt, 0.35);
          this.coresGfx.strokeCircle(cx, coreY, CORE_INNER_RADIUS);
        }
      }
    }

    // 캐릭터 이름
    const nameText = this.add.text(x, y + CARD_H / 2 - 16, char.name, {
      fontSize: '12px',
      color: isOwned ? '#ffffff' : '#555555',
      fontStyle: 'bold',
    }).setOrigin(0.5);
    this.cardsContainer.add(nameText);

    // 모든 카드 클릭 가능 (탭 → 상세 패널 열기)
    cardBg.setInteractive({ useHandCursor: isOwned });

    if (isOwned) {
      cardBg.on('pointerover', () => {
        if (this.selectedId !== char.id) cardBg.setFillStyle(0x333333);
      });
      cardBg.on('pointerout', () => {
        if (this.selectedId !== char.id) cardBg.setFillStyle(0x222222);
      });
    }
    // pointerup으로 상세 패널 열기 (드래그 스크롤과 구분, 이전 씬 bleed-through 방지)
    cardBg.on('pointerup', () => {
      if (!this.hasDragged && this.hasPointerDownInScene) this.showCharacterDetail(char.id);
    });
  }

  private selectCharacter(id: string) {
    // 이전 선택 하이라이트 제거
    const prev = this.cardHighlights.get(this.selectedId);
    if (prev) prev.setVisible(false);

    this.selectedId = id;
    setSelectedCharacter(id);

    const next = this.cardHighlights.get(id);
    if (next) next.setVisible(true);

    // 헤더 직접 갱신 (씬 재시작 없이)
    const def = CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
    this.headerNameText.setText(`현재: ${def.name}`);
    this.headerNameText.setColor(def.gradeColor);
    this.bgImage.setTexture(def.illustKey);
  }

  private showCharacterDetail(id: string): void {
    this.hideCharacterDetail();

    const def = CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
    const isOwned = this.ownedIds.includes(id);
    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);

    const panel = this.add.container(0, 0).setDepth(300);
    this.detailPanel = panel;

    // ── 클릭 투과 차단 레이어 (카드 목록으로 이벤트 전달 방지)
    const blocker = this.add.rectangle(200, 300, 400, 600, 0x000000, 0).setInteractive();
    panel.add(blocker);

    // ── 일러스트 전체 화면 ───────────────────────────────────────────
    const illust = this.add.image(200, 300, def.illustKey).setDisplaySize(400, 600);
    panel.add(illust);

    // ── 비디오 (일러스트와 같은 위치, 처음엔 숨김) ─────────────────
    const hasVideo = !!(def.videoKey && this.cache.video.exists(def.videoKey));
    const videoObj = hasVideo
      ? this.add.video(200, 300, def.videoKey!).setDisplaySize(400, 600).setVisible(false)
      : null;
    if (videoObj) {
      panel.add(videoObj);
      this.detailVideo = videoObj;
    }

    // ── 하단 그라디언트 (위 투명 → 아래 짙은 어둠) ─────────────────
    // 비디오/일러스트 위, 버튼 아래에 위치하도록 여기서 추가
    const grad = this.add.graphics();
    grad.fillGradientStyle(0x000000, 0x000000, 0x000000, 0x000000, 0, 0, 0.78, 0.78);
    grad.fillRect(0, 380, 400, 220);
    panel.add(grad);

    // ── ✕ 닫기 버튼 (우상단 플로팅) ────────────────────────────────
    const closeBg = this.add.circle(372, 38, 22, 0x000000, 0.55)
      .setInteractive({ useHandCursor: true });
    const closeBtn = this.add.text(372, 38, '✕', {
      fontSize: '18px', color: '#cccccc',
    }).setOrigin(0.5);
    closeBg.on('pointerover', () => { closeBg.setFillStyle(0x333333, 0.8); closeBtn.setColor('#ffffff'); });
    closeBg.on('pointerout',  () => { closeBg.setFillStyle(0x000000, 0.55); closeBtn.setColor('#cccccc'); });
    closeBg.on('pointerup',   () => this.hideCharacterDetail());
    panel.add(closeBg);
    panel.add(closeBtn);

    // ── 하단 정보 영역 ───────────────────────────────────────────────
    // 픽셀 스프라이트
    const sprite = this.add.image(38, 515, def.imageKey).setDisplaySize(46, 64);
    if (!isOwned) { sprite.setTint(0x222222).setAlpha(0.55); }
    panel.add(sprite);

    // 등급 배지
    const gradeBadge = this.add.text(74, 492, def.grade, {
      fontSize: '12px', color: def.gradeColor, fontStyle: 'bold',
      stroke: '#000000', strokeThickness: 4,
    });
    panel.add(gradeBadge);

    // 캐릭터 이름 (크게)
    const nameText = this.add.text(74, 510, def.name, {
      fontSize: '26px', color: '#ffffff', fontStyle: 'bold',
      stroke: '#000000', strokeThickness: 5,
    });
    panel.add(nameText);

    // ── 하단 버튼 2개 (나란히) ──────────────────────────────────────
    const BTN_Y = 568;
    const BTN_W = 168;
    const BTN_H = 42;

    // 📋 정보 보기 (좌)
    const infoBg = this.add.rectangle(108, BTN_Y, BTN_W, BTN_H, 0x1a1a1a)
      .setStrokeStyle(1.5, 0x555555)
      .setInteractive({ useHandCursor: true });
    infoBg.on('pointerover', () => infoBg.setFillStyle(0x2e2e2e));
    infoBg.on('pointerout',  () => infoBg.setFillStyle(0x1a1a1a));
    infoBg.on('pointerup',   () => this.showInfoPanel(def));
    const infoLabel = this.add.text(108, BTN_Y, '📋  정보 보기', {
      fontSize: '14px', color: '#cccccc', fontStyle: 'bold',
    }).setOrigin(0.5);
    panel.add(infoBg);
    panel.add(infoLabel);

    // ✔ 선택하기 / 🔒 미보유 (우)
    if (isOwned) {
      const selBg = this.add.rectangle(292, BTN_Y, BTN_W, BTN_H, 0x1144bb)
        .setStrokeStyle(2, gradeColorInt)
        .setInteractive({ useHandCursor: true });
      selBg.on('pointerover', () => selBg.setFillStyle(0x2860dd));
      selBg.on('pointerout',  () => selBg.setFillStyle(0x1144bb));
      selBg.on('pointerup',   () => this.confirmSelect(id));
      const selLabel = this.add.text(292, BTN_Y, '✔  선택하기', {
        fontSize: '15px', color: '#ffffff', fontStyle: 'bold',
        stroke: '#000000', strokeThickness: 2,
      }).setOrigin(0.5);
      panel.add(selBg);
      panel.add(selLabel);
    } else {
      const lockBg = this.add.rectangle(292, BTN_Y, BTN_W, BTN_H, 0x1a1a1a)
        .setStrokeStyle(1.5, 0x444444);
      const lockLabel = this.add.text(292, BTN_Y, '🔒  미보유', {
        fontSize: '14px', color: '#555555',
      }).setOrigin(0.5);
      panel.add(lockBg);
      panel.add(lockLabel);
    }

    // ── 비디오 인터랙션 (비디오가 있는 캐릭터만) ────────────────────
    if (hasVideo && videoObj) {
      // 일러스트 탭 → 비디오 재생 (가챠와 동일한 fitVideo 방식)
      // active 체크: ✕ 탭 시 패널 파괴 직후 이 핸들러가 동시에 발화하는 경우 방지
      const startVideo = () => {
        if (!illust.active || !videoObj?.active) return;
        videoObj!.setVisible(true);
        videoObj!.play(false);
        this.fitVideoToPanel(videoObj!);
        // 비디오 'play' 이벤트 = 실제 재생 시작 시점 → 그때 일러스트 숨김
        // (즉시 숨기면 첫 프레임 렌더 전 갭에 카드 목록이 비침)
        videoObj!.once('play', () => {
          if (illust.active) illust.setVisible(false);
        });
      };
      illust.setInteractive({ useHandCursor: true });
      illust.on('pointerup', startVideo);

      // 비디오 탭 또는 재생 완료 → 일러스트로 복귀
      const stopVideo = () => {
        videoObj!.stop();
        videoObj!.setVisible(false);
        illust.setVisible(true);
      };
      videoObj.setInteractive({ useHandCursor: true });
      videoObj.on('pointerup', stopVideo);
      videoObj.on('complete', stopVideo);
    }
  }

  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
    const W = 400, H = 600;
    vid.setDisplaySize(W, H);

    const applyContain = () => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const el: HTMLVideoElement | null = (vid as any).video ?? null;
      const nw = el?.videoWidth  || 0;
      const nh = el?.videoHeight || 0;
      if (nw > 0 && nh > 0) {
        const scale = Math.max(W / nw, H / nh);
        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
      }
    };

    vid.once('play', applyContain);
    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
  }

  private hideCharacterDetail(): void {
    // fitVideoToPanel의 pending 타이머 취소
    for (const t of this.fitVideoTimers) t.remove();
    this.fitVideoTimers = [];

    // 비디오 명시 정지 및 HTMLVideoElement src 해제
    if (this.detailVideo) {
      this.detailVideo.stop();
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const el: HTMLVideoElement | null = (this.detailVideo as any).video ?? null;
      if (el) { el.src = ''; }
      this.detailVideo = null;
    }

    this.hideInfoPanel();
    this.detailPanel?.destroy();
    this.detailPanel = null;
  }

  private confirmSelect(id: string): void {
    this.selectCharacter(id);
    this.hideCharacterDetail();
  }

  private showInfoPanel(def: CharacterDef): void {
    this.hideInfoPanel();

    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);
    const panel = this.add.container(0, 0).setDepth(400);
    this.infoPanel = panel;

    // ── 각성 보너스 계산 ──────────────────────────────────────────────
    const dupCount   = getDuplicateCount(def.id);
    const awakeLevel = getAwakeningLevel(def.grade, dupCount);
    const awakeBonusLines: string[] = [];
    if (def.grade !== '등급외') {
      if (awakeLevel >= 1) {
        const spd = def.id === 'maehwa' ? 5 : def.grade === 'UR' ? 15 : def.grade === 'SR' ? 10 : 5;
        awakeBonusLines.push(`★1 각성: 이동속도 +${spd} px/s`);
      }
      if (awakeLevel >= 2) {
        if (def.id === 'maehwa') {
          awakeBonusLines.push('★2 각성: 특수 똥 수집 시 +5점');
        } else {
          const spd = def.grade === 'UR' ? 20 : def.grade === 'SR' ? 15 : 10;
          awakeBonusLines.push(`★2 각성: 이동속도 +${spd} px/s (누적)`);
        }
      }
    }
    const awakeBonusText = awakeBonusLines.join('\n');

    // 반투명 배경 (클릭 시 닫기)
    const overlay = this.add.rectangle(200, 300, 400, 600, 0x000000, 0.80)
      .setInteractive();
    overlay.on('pointerup', () => this.hideInfoPanel());
    panel.add(overlay);

    // ── 카드 크기 계산 (텍스트 높이 선측정) ─────────────────────────
    const B_LEFT = 30;
    const CARD_W = 370;
    const WRAP_W = CARD_W - 40; // 좌(15px)·우(25px) 여백 제외한 실제 텍스트 폭
    const HEADER_H = 60;  // 스프라이트+이름+구분선 영역
    const PAD_BOT  = 20;

    const btMeasure = this.add.text(0, -999, def.basicEffect,    { fontSize: '13px', wordWrap: { width: WRAP_W } });
    const stMeasure = this.add.text(0, -999, def.specialAbility, { fontSize: '13px', wordWrap: { width: WRAP_W } });
    const abMeasure = awakeBonusText
      ? this.add.text(0, -999, awakeBonusText, { fontSize: '12px', wordWrap: { width: WRAP_W } })
      : null;
    const abHeight  = abMeasure ? abMeasure.height + 8 : 0;
    const cardH = HEADER_H + 18 + btMeasure.height + abHeight + 14 + 18 + stMeasure.height + PAD_BOT;
    btMeasure.destroy();
    stMeasure.destroy();
    abMeasure?.destroy();

    // 화면 중앙 배치 (상하 여백 각 70px 보장)
    const cardTop = Math.max(70, Math.round((600 - cardH) / 2));
    const card = this.add.rectangle(200, cardTop + cardH / 2, CARD_W, cardH, 0x111111)
      .setStrokeStyle(2, gradeColorInt);
    panel.add(card);

    // ── 헤더: 픽셀 스프라이트 + 등급 + 이름 ─────────────────────────
    const sprite = this.add.image(52, cardTop + 24, def.imageKey).setDisplaySize(38, 52);
    panel.add(sprite);

    const badge = this.add.text(82, cardTop + 8, def.grade, {
      fontSize: '11px', color: def.gradeColor, fontStyle: 'bold',
      stroke: '#000000', strokeThickness: 3,
    });
    panel.add(badge);

    const name = this.add.text(82, cardTop + 24, def.name, {
      fontSize: '17px', color: '#ffffff', fontStyle: 'bold',
      stroke: '#000', strokeThickness: 3,
    });
    panel.add(name);

    // ✕ 닫기 (헤더 우측)
    const closeX = 200 + CARD_W / 2 - 14;
    const closeY = cardTop + 16;
    const infoBtnBg = this.add.circle(closeX, closeY, 18, 0x000000, 0)
      .setInteractive({ useHandCursor: true });
    const closeTxt = this.add.text(closeX, closeY, '✕', {
      fontSize: '16px', color: '#999999',
    }).setOrigin(0.5);
    infoBtnBg.on('pointerover', () => closeTxt.setColor('#ffffff'));
    infoBtnBg.on('pointerout',  () => closeTxt.setColor('#999999'));
    infoBtnBg.on('pointerup',   () => this.hideInfoPanel());
    panel.add(infoBtnBg);
    panel.add(closeTxt);

    // 구분선
    panel.add(this.add.rectangle(200, cardTop + HEADER_H - 4, CARD_W - 20, 1, 0x444444));

    // ── 기본 효과 ─────────────────────────────────────────────────────
    let curY = cardTop + HEADER_H + 4;

    panel.add(this.add.text(B_LEFT, curY, '🔷 기본 효과', {
      fontSize: '12px', color: '#88bbff', fontStyle: 'bold',
    }));
    curY += 18;

    const basicText = this.add.text(B_LEFT, curY, def.basicEffect, {
      fontSize: '13px', color: '#eeeeee', wordWrap: { width: WRAP_W },
    });
    panel.add(basicText);
    curY += basicText.height;

    if (awakeBonusText) {
      curY += 8;
      panel.add(this.add.text(B_LEFT, curY, awakeBonusText, {
        fontSize: '12px', color: '#ffd700', wordWrap: { width: WRAP_W },
      }));
      curY += (abHeight - 8);
    }

    curY += 14;

    // ── 특수 능력 ─────────────────────────────────────────────────────
    panel.add(this.add.text(B_LEFT, curY, '⚡ 특수 능력', {
      fontSize: '12px', color: '#ffdd88', fontStyle: 'bold',
    }));
    curY += 18;

    panel.add(this.add.text(B_LEFT, curY, def.specialAbility, {
      fontSize: '13px',
      color: def.specialAbility === '없음' ? '#666666' : '#eeeeee',
      wordWrap: { width: WRAP_W },
    }));
  }

  private hideInfoPanel(): void {
    this.infoPanel?.destroy();
    this.infoPanel = null;
  }

  private createBackButton() {
    const btn = this.add.rectangle(200, 573, 200, 50, 0x333333);
    btn.setStrokeStyle(2, 0x888888);

    this.add.text(200, 573, '← 돌아가기', {
      fontSize: '18px',
      color: '#ffffff',
      fontStyle: 'bold',
    }).setOrigin(0.5);

    btn.setInteractive({ useHandCursor: true });
    btn.on('pointerover', () => btn.setFillStyle(0x555555));
    btn.on('pointerout',  () => btn.setFillStyle(0x333333));
    btn.on('pointerdown', () => this.scene.start('ModeSelectScene'));
  }
}

import Phaser from 'phaser';
import { gachaPull, syncOwnedCharacters, syncOwnedWallpapers, type PulledCharacter, type PulledWallpaper } from '../utils/gacha';
import { CHARACTERS, getCharacterDef, addOwnedCharacter, getDuplicateCount, setDuplicateCount, type CharacterDef } from '../utils/character';
import { WALLPAPERS, addOwnedWallpaper, WP_ACCENT_INT, WP_ACCENT_HEX, type BackgroundDef } from '../utils/wallpaper';
import { getSkorBalance, getCachedSkorBalance, cacheSkorBalance } from '../utils/skor';

// vids/ 디렉토리에 개인 영상이 존재하는 캐릭터 목록
const CHARS_WITH_VIDS = new Set([
  'chibi', 'hacker', 'miner', 'maehwa', 'archieve', 'glitch', 'noise', 'sentinel', 'legacy',
]);

const GRADE_COLORS: Record<string, number> = {
  UR: 0xffaa00,
  SR: 0x4488ff,
  R:  0x44bb44,
  N:  0xaaaaaa,
  '등급외': 0xcccccc,
};

// 현재 픽업 배너 설정 — 출시 캐릭터 변경 시 characterId만 수정
const CURRENT_BANNER = {
  characterId: 'legacy',
  label: '신규 출시',
};

// 로비 슬라이드쇼 순서: UR 우선(sentinel → legacy), 이후 SR 순
const SLIDESHOW_IDS = ['sentinel', 'legacy', 'hacker', 'miner', 'maehwa', 'archieve', 'glitch', 'noise'];

export default class GachaScene extends Phaser.Scene {
  private skorBalance = 0;
  private remainingSkor = 0;
  private pullResults: PulledCharacter[] = [];
  private wpResults: PulledWallpaper[] = [];
  private revealItems: Array<{ kind: 'character'; data: PulledCharacter } | { kind: 'wallpaper'; data: PulledWallpaper }> = [];
  private revealItemIndex = 0;
  private terminalTexts: Phaser.GameObjects.Text[] = [];
  private skipTerminal = false;

  // ── 로비 슬라이드쇼 상태 ──
  private slideshowIndex = 0;
  private slideshowIsA = true; // true → bgA가 현재 레이어
  private slideshowBgA: Phaser.GameObjects.Image | null = null;
  private slideshowBgB: Phaser.GameObjects.Image | null = null;
  private slideshowGradeText: Phaser.GameObjects.Text | null = null;
  private slideshowNameText: Phaser.GameObjects.Text | null = null;
  private slideshowBadgeBox: Phaser.GameObjects.Rectangle | null = null;
  private slideshowBadgeTxt: Phaser.GameObjects.Text | null = null;
  private slideshowActive = false;

  constructor() {
    super('GachaScene');
  }

  preload() {
    // 공통 연출 영상
    if (!this.cache.video.exists('gacha')) {
      this.load.video('gacha', 'assets/vids/gacha.mp4');
    }
    // 캐릭터 픽셀 이미지 (작은 webp, 전부 사전 로드)
    for (const c of CHARACTERS) {
      if (!this.textures.exists(c.imageKey)) {
        this.load.image(c.imageKey, c.imagePath);
      }
    }
    // 슬라이드쇼 캐릭터 일러스트 전체 사전 로드
    for (const id of SLIDESHOW_IDS) {
      const def = CHARACTERS.find(c => c.id === id);
      if (def && !this.textures.exists(def.illustKey)) {
        this.load.image(def.illustKey, def.illustPath);
      }
    }
    // 리빌 화면 공통 배경
    if (!this.textures.exists('gacha_background')) {
      this.load.image('gacha_background', 'assets/backgrounds/gacha_background.webp');
    }
  }

  create() {
    this.pullResults = [];
    this.revealItems = [];
    this.revealItemIndex = 0;
    this.buildLobby();
  }

  // ═══════════════════════════════════════════════════
  // LOBBY
  // ═══════════════════════════════════════════════════

  private async buildLobby() {
    this.slideshowActive = false;
    this.clearUI();

    this.slideshowIndex = 0;
    this.slideshowIsA = true;

    const currentDef = getCharacterDef(SLIDESHOW_IDS[0]);
    const gradeColorInt = parseInt(currentDef.gradeColor.replace('#', ''), 16);

    // ── 일러스트 배경 2레이어 (crossfade용) ──
    // bgA: 처음엔 현재 일러스트 (alpha=1), bgB: 다음 일러스트 대기 (alpha=0)
    this.slideshowBgA = this.add.image(200, 300, currentDef.illustKey).setDisplaySize(400, 600);
    this.slideshowBgB = this.add.image(200, 300, currentDef.illustKey).setDisplaySize(400, 600).setAlpha(0);

    // ── 하단 버튼 영역 그라데이션 ──
    const gradSteps = 14;
    for (let i = 0; i < gradSteps; i++) {
      this.add.rectangle(200, 600 - i * 22, 400, 22, 0x000000, (gradSteps - i) * 0.052);
    }

    // ── 상단: 배너 배지 (슬라이드마다 등급 색상 업데이트) ──
    this.slideshowBadgeBox = this.add.rectangle(200, 36, 140, 30, 0x000000, 0.75)
      .setStrokeStyle(1.5, gradeColorInt);
    this.slideshowBadgeTxt = this.add.text(200, 36, `✦  ${CURRENT_BANNER.label}  ✦`, {
      fontSize: '13px', color: currentDef.gradeColor, fontStyle: 'bold',
      stroke: '#000000', strokeThickness: 3,
    }).setOrigin(0.5);

    // ── 캐릭터 등급 + 이름 — SKOR 잔액(y=408) 바로 위, 겹침 없도록 배치 ──
    // grade(13px ≈ 16px high) y=344 → 336~352
    // name (28px ≈ 34px high) y=374 → 357~391
    // SKOR(15px)              y=408 → 399~417  (gap ≈ 8px)
    this.slideshowGradeText = this.add.text(200, 344, currentDef.grade, {
      fontSize: '13px', color: currentDef.gradeColor, fontStyle: 'bold',
      letterSpacing: 6, stroke: '#000000', strokeThickness: 5,
    }).setOrigin(0.5);

    this.slideshowNameText = this.add.text(200, 374, currentDef.name, {
      fontSize: '28px', color: '#ffffff', fontStyle: 'bold',
      stroke: '#000000', strokeThickness: 8,
    }).setOrigin(0.5);

    // ── SKOR 잔액 ──
    const cached = getCachedSkorBalance();
    const initialText = cached !== null ? `💰  ${cached} SKOR` : '💰  -- SKOR';
    const skorText = this.add.text(200, 408, initialText, {
      fontSize: '15px', color: '#aaaaaa',
      stroke: '#000000', strokeThickness: 4,
    }).setOrigin(0.5);
    this.skorBalance = -1;

    // ── 뽑기 버튼 ──
    this.buildPullButtons(true);

    // ── 슬라이드쇼 타이머 (2초마다 자동 전환) ──
    this.slideshowActive = true;
    this.time.addEvent({
      delay: 2000,
      loop: true,
      callback: this.advanceSlide,
      callbackScope: this,
    });

    // 서버에서 최신 잔액 가져와 갱신
    this.skorBalance = await getSkorBalance();
    if (!this.scene.isActive()) return;
    cacheSkorBalance(this.skorBalance);
    skorText.setText(`💰  ${Math.floor(this.skorBalance)} SKOR`);
  }

  private advanceSlide() {
    if (!this.slideshowActive || !this.scene.isActive()) return;

    const nextIndex = (this.slideshowIndex + 1) % SLIDESHOW_IDS.length;
    const nextDef = getCharacterDef(SLIDESHOW_IDS[nextIndex]);

    // 현재/다음 레이어 결정
    const current  = this.slideshowIsA ? this.slideshowBgA : this.slideshowBgB;
    const incoming = this.slideshowIsA ? this.slideshowBgB : this.slideshowBgA;
    if (!current || !incoming) return;

    // 다음 일러스트를 incoming 레이어에 세팅
    incoming.setTexture(nextDef.illustKey).setAlpha(0);

    // 상태 + 텍스트를 일러스트 전환 시작과 동시에 즉시 교체
    this.slideshowIsA = !this.slideshowIsA;
    this.slideshowIndex = nextIndex;
    this.updateSlideshowText(nextDef);

    // crossfade: 현재 fade-out, 다음 fade-in
    this.tweens.add({ targets: current,  alpha: 0, duration: 600, ease: 'Sine.easeInOut' });
    this.tweens.add({ targets: incoming, alpha: 1, duration: 600, ease: 'Sine.easeInOut' });
  }

  private updateSlideshowText(def: ReturnType<typeof getCharacterDef>) {
    const gradeColorInt = parseInt(def.gradeColor.replace('#', ''), 16);

    // 배지 색상 즉시 교체
    this.slideshowBadgeBox?.setStrokeStyle(1.5, gradeColorInt);
    this.slideshowBadgeTxt?.setColor(def.gradeColor);

    // 등급·이름: 즉시 텍스트 교체 후 짧게 fade-in (150ms)
    if (this.slideshowGradeText?.active) {
      this.slideshowGradeText.setText(def.grade).setColor(def.gradeColor).setAlpha(0);
      this.tweens.add({ targets: this.slideshowGradeText, alpha: 1, duration: 150 });
    }
    if (this.slideshowNameText?.active) {
      this.slideshowNameText.setText(def.name).setAlpha(0);
      this.tweens.add({ targets: this.slideshowNameText, alpha: 1, duration: 150 });
    }
  }

  private drawTerminalChrome(isUR = false) {
    const borderColor = isUR ? 0xff3333 : 0x00ff41;
    const textColor   = isUR ? '#ff3333' : '#00ff41';
    const titleColor  = isUR ? '#cc0000' : '#00cc33';
    const title       = isUR ? 'root@krypt — [EMERGENCY OVERRIDE]' : 'root@krypt — entity_summon';

    this.add.rectangle(200, 342, 370, 172, 0x000000)
      .setStrokeStyle(1, borderColor, 0.8);
    this.add.text(26, 260, '● ● ●', { fontSize: '11px', color: textColor });
    this.add.text(200, 261, title, {
      fontSize: '11px', color: titleColor, fontFamily: 'monospace',
    }).setOrigin(0.5);
  }

  private buildPullButtons(_fromLobby = false) {
    this.addPullButton(200, 448, '1회 소환', '100 SKOR', 'single');
    this.addPullButton(200, 516, '10회 소환', '900 SKOR  ·  10% 절약', 'multi');

    const back = this.add.text(200, 572, '← 돌아가기', {
      fontSize: '14px', color: '#ffffff',
      stroke: '#000000', strokeThickness: 3,
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    back.on('pointerover', () => back.setColor('#cccccc'));
    back.on('pointerout',  () => back.setColor('#ffffff'));
    back.on('pointerdown', () => this.scene.start('ModeSelectScene'));
  }

  private addPullButton(x: number, y: number, label: string, cost: string, type: 'single' | 'multi') {
    const accentColor = type === 'single' ? 0xddaa00 : 0x7b2fff;
    const accentHex   = type === 'single' ? '#ddaa00' : '#aa88ff';

    const btn = this.add.rectangle(x, y, 310, 52, 0x000000, 0.72)
      .setStrokeStyle(1.5, accentColor)
      .setInteractive({ useHandCursor: true });

    this.add.text(x, y - 9, label, {
      fontSize: '20px', color: '#ffffff', fontStyle: 'bold',
    }).setOrigin(0.5);
    this.add.text(x, y + 13, cost, {
      fontSize: '12px', color: accentHex,
    }).setOrigin(0.5);

    btn.on('pointerover', () => btn.setStrokeStyle(2.5, accentColor));
    btn.on('pointerout',  () => btn.setStrokeStyle(1.5, accentColor));
    btn.on('pointerdown', () => this.startPull(type));
  }

  // ═══════════════════════════════════════════════════
  // PULL FLOW
  // ═══════════════════════════════════════════════════

  private async startPull(type: 'single' | 'multi') {
    const cost = type === 'multi' ? 900 : 100;
    if (this.skorBalance < 0) {
      const errMsg = this.add.text(200, 370, '잔액 확인 중... 잠시 후 다시 시도하세요', {
        fontSize: '13px', color: '#ffaa44',
        stroke: '#000000', strokeThickness: 3,
        backgroundColor: '#00000099',
        padding: { x: 10, y: 5 },
      }).setOrigin(0.5);
      this.time.delayedCall(2000, () => { if (errMsg.active) errMsg.destroy(); });
      return;
    }
    if (this.skorBalance < cost) {
      const errMsg = this.add.text(200, 370, `SKOR 부족  (보유 ${Math.floor(this.skorBalance)} / 필요 ${cost})`, {
        fontSize: '13px', color: '#ff5555',
        stroke: '#000000', strokeThickness: 3,
        backgroundColor: '#00000099',
        padding: { x: 10, y: 5 },
      }).setOrigin(0.5);
      this.time.delayedCall(2200, () => { if (errMsg.active) errMsg.destroy(); });
      return;
    }

    this.clearUI();

    const count = type === 'multi' ? 10 : 1;

    try {
      // ① 영상(6초) + API 호출 병렬 실행 — 영상 보는 동안 응답 대기
      const [result] = await Promise.all([
        gachaPull(type),
        this.playCommonVideo(),
      ]);

      if (!this.scene.isActive()) return;

      this.pullResults = result.characters;
      this.wpResults = result.wallpapers ?? [];
      this.remainingSkor = result.remainingSkor;
      // 슬롯 순서 보존: 캐릭터 → 배경 순 통합 큐
      this.revealItems = [
        ...result.characters.map(c => ({ kind: 'character' as const, data: c })),
        ...(result.wallpapers ?? []).map(w => ({ kind: 'wallpaper' as const, data: w })),
      ];
      this.revealItemIndex = 0;

      // ① 결과의 신규 캐릭터 즉시 저장 (sync 실패 대비 fallback)
      result.characters.filter(c => c.isNew).forEach(c => addOwnedCharacter(c.id));
      // ① 중복 캐릭터 각성 카운트 업데이트
      result.characters.filter(c => !c.isNew).forEach(c => {
        setDuplicateCount(c.id, getDuplicateCount(c.id) + 1);
      });
      // ① 신규 배경화면 즉시 저장 (sync 실패 대비 fallback)
      this.wpResults.filter(w => w.isNew).forEach(w => addOwnedWallpaper(w.id));
      // ② 서버 DB 전체 동기화 (비동기, 에러 로그만)
      syncOwnedCharacters().catch(e => console.error('[GachaScene] syncOwnedCharacters 실패:', e));
      syncOwnedWallpapers().catch(e => console.error('[GachaScene] syncOwnedWallpapers 실패:', e));

      // ② 터미널 애니메이션 (UR이면 중반부터 빨간 에러 스타일로 전환)
      const isUR = result.video === 'red'
      this.skipTerminal = false;
      this.clearUI();
      this.add.rectangle(200, 300, 400, 600, 0x000000);
      this.drawTerminalChrome(false); // 항상 초록으로 시작
      this.addSkipButton(() => { this.skipTerminal = true; });
      await this.runTerminalAnimation(count, isUR);
      this.skipTerminal = false;

      // ③ 캐릭터별 개인 영상 + 배경화면 이미지 동적 로드 → 리빌
      await Promise.all([
        this.loadCharVideos(result.characters.map(c => c.id)),
        this.loadWallpaperBgs(this.wpResults.map(w => w.id)),
      ]);

      this.showNextReveal();
    } catch {
      if (!this.scene.isActive()) return;
      await this.typeLines([
        '> CONNECTION ERROR',
        '> Retrying in 3s...',
      ], 30);
      this.time.delayedCall(3000, () => this.buildLobby());
    }
  }

  private async runTerminalAnimation(count: number, isUR = false): Promise<void> {
    if (isUR) {
      const red = '#ff3333';
      // 초반: 정상처럼 초록으로 시작
      await this.typeLines([
        `> EXECUTE entity_summon(n=${count})`,
        '> Establishing connection...',
      ], 18);
      await this.progressBar(400);
      await this.typeLines([
        '> CONN: OK  [sec-layer bypassed]',
        '> Scanning entity pool...',
      ], 16);
      await this.progressBar(350);
      // 이상 감지 시점부터 빨간색으로 전환
      await this.typeLines([
        '> [WARN] Anomaly detected',
        '> [ERR]  Containment failure',
      ], 18, red);
      await this.progressBar(450, red);
      await this.typeLines([
        '> [CRIT] Unknown entity detected',
        `> [!!!]  ${count} ENTR${count > 1 ? 'IES' : 'Y'} ESCAPED CONTAINMENT`,
        '> EMERGENCY EXTRACTION . . .',
      ], 20, red);
    } else {
      await this.typeLines([
        `> EXECUTE entity_summon(n=${count})`,
        '> Establishing connection...',
      ], 18);
      await this.progressBar(400);
      await this.typeLines([
        '> CONN: OK  [sec-layer bypassed]',
        '> Scanning entity pool...',
      ], 16);
      await this.progressBar(350);
      await this.typeLines([
        '> Anomaly detected in sector 7',
        '> Overriding...',
      ], 18);
      await this.progressBar(450);
      await this.typeLines([
        `> ${count} ENTR${count > 1 ? 'IES' : 'Y'} LOCKED`,
        '> EXTRACTING . . .',
      ], 20);
    }
    await this.sleep(200);
  }

  /** 영상 원본 비율을 유지하면서 캔버스 안에 꽉 차게 (contain) */
  private fitVideoToCanvas(vid: Phaser.GameObjects.Video, canvasW: number, canvasH: number) {
    vid.setDisplaySize(canvasW, canvasH); // 초기값

    const applyContain = () => {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const el: HTMLVideoElement | null = (vid as any).video ?? null;
      const nw = el?.videoWidth  || 0;
      const nh = el?.videoHeight || 0;
      if (nw > 0 && nh > 0) {
        const scale = Math.max(canvasW / nw, canvasH / nh);
        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
      }
    };

    vid.once('play', applyContain);
    this.time.delayedCall(100, applyContain);
    this.time.delayedCall(500, applyContain);
  }

  private loadWallpaperBgs(ids: string[]): Promise<void> {
    const toLoad = ids.filter(id => {
      const def = WALLPAPERS.find(w => w.id === id);
      return def && !this.textures.exists(def.bgKey);
    });
    if (toLoad.length === 0) return Promise.resolve();

    return new Promise(resolve => {
      toLoad.forEach(id => {
        const def = WALLPAPERS.find(w => w.id === id);
        if (def) this.load.image(def.bgKey, def.bgPath);
      });
      this.load.once(Phaser.Loader.Events.COMPLETE, resolve);
      this.load.once(Phaser.Loader.Events.FILE_LOAD_ERROR, resolve);
      this.load.start();
    });
  }

